def detect_inversion(row):
    """Detect if the row has a 2 appearing after a 3 (an inversion), meaning 2s become 1s"""
    # If 2 appears after 3, we have 3s followed by some 2s
    for i in range(len(row) - 1):
        if row[i] == 3 and row[i + 1] == 2:
            return True
    return False

def has_2_and_3(grid_row):
    return 2 in grid_row and 3 in grid_row

def transform(grid):
    result = [row[:] for row in grid]  # copy
    for r in range(len(result)):
        if has_2_and_3(result[r]):
            for c in range(len(result[r])):
                if result[r][c] == 2:
                    result[r][c] = 1
    return result

