def transform_demo(grid):
    """For each 2, if 4-connected to a 3, it becomes 1."""
    rows, cols = len(grid), len(grid[0])
    seen_3s = set()
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                seen_3s.add((r, c))

    from collections import deque
    queue = deque(seen_3s)
    connected_to_3 = set()

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in connected_to_3 and grid[nr][nc] in (3, 2):
                    connected_to_3.add((nr, nc))
                    if grid[nr][nc] == 2:
                        queue.append((nr, nc))

    for r in range(rows):
        for c in range(cols):
            if (r, c) in connected_to_3 and grid[r][c] == 2:
                output[r][c] = 1

    return output

